pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        vm.deal(address(0x1), 20 ether);
        vm.prank(address(0x1));
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);
        vm.warp(block.timestamp + 1);
        vm.prank(address(0x1));
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(address(c).balance % 10 ether == 0 || address(c).balance % 10 ether == 10 ether);
        assertTrue(address(c).balance == 10 ether);
    }
}
